class Averageprice30(SQLModel, table=True):
    __table_args__ = (
        PrimaryKeyConstraint('perioddate', 'regionid', name='averageprice30_pk'),
        {'comment': 'Reflects the 30-minute average price (the pre-5MS trading price).'}
    )

    perioddate: datetime.datetime = Field(sa_column=Column('perioddate', TIMESTAMP(precision=0), primary_key=True, comment='30-minute interval period, 1 to 48 from the start of the calendar day'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region Identifier'))
    periodid: decimal.Decimal = Field(sa_column=Column('periodid', Numeric(3, 0), nullable=False, comment='The 30-minute interval period, 1 to 48'))
