    paymentdate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('paymentdate', TIMESTAMP(precision=0), comment='Payment Date'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))
    revision1_statementdate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('revision1_statementdate', TIMESTAMP(precision=0), comment='Revision 1 Statement Date for the billing week.'))
