    fcasimportlimit: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fcasimportlimit', Numeric(15, 5), comment='Calculated import limit applying to energy + FCAS.'))
    local_price_adjustment_export: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('local_price_adjustment_export', Numeric(10, 2), comment='Aggregate Constraint contribution cost of this Interconnector: Sum(MarginalValue x Factor) for all relevant Constraints, for Export (Factor >= 0)'))
    locally_constrained_export: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('locally_constrained_export', Numeric(1, 0), comment='Key for Local_Price_Adjustment_Export: 2 = at least one Outage Constraint; 1 = at least 1 System Normal Constraint (and no Outage Constraint); 0 = No System Normal or Outage Constraints'))
    local_price_adjustment_import: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('local_price_adjustment_import', Numeric(10, 2), comment='Aggregate Constraint contribution cost of this Interconnector: Sum(MarginalValue x Factor) for all relevant Constraints, for Import (Factor >= 0)'))
    locally_constrained_import: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('locally_constrained_import', Numeric(1, 0), comment='Key for Local_Price_Adjustment_Import: 2 = at least one Outage Constraint; 1 = at least 1 System Normal Constraint (and no Outage Constraint); 0 = No System Normal or Outage Constraints'))


