    dispatchtype: Optional[str] = Field(default=None, sa_column=Column('dispatchtype', String(20), comment='Identifies LOAD, GENERATOR or BIDIRECTIONAL. This will likely expand to more generic models as new technology types are integrated into the NEM'))
    connectionpointid: Optional[str] = Field(default=None, sa_column=Column('connectionpointid', String(10), comment='Country wide - Unique id of a connection point'))
