    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))
    transmissionlossfactor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('transmissionlossfactor', Numeric(15, 5), comment='Used in Bidding, Dispatch and Settlements. For Bidding and Dispatch, where the DUID is a BDU with DISPATCHTYPE of BIDIRECTIONAL, the TLF for the load component of the BDU. For Settlements, where dual TLFs apply, the primary TLF is applied to all energy (load and generation) when the Net Energy Flow of the ConnectionPointID in the interval is negative (net load).'))
    starttype: Optional[str] = Field(default=None, sa_column=Column('starttype', String(20), comment='Unit start type. At this time restricted to Fast, Slow or Non Dispatched'))
    distributionlossfactor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('distributionlossfactor', Numeric(15, 5), comment='The distribution loss factor to the currently assigned connection point'))
    minimum_energy_price: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('minimum_energy_price', Numeric(9, 2), comment='Floored Offer/Bid Energy Price adjusted for TLF, DLF and MPF'))
    maximum_energy_price: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maximum_energy_price', Numeric(9, 2), comment='Capped Offer/Bid Energy Price adjusted for TLF, DLF and VoLL'))
    schedule_type: Optional[str] = Field(default=None, sa_column=Column('schedule_type', String(20), comment="Scheduled status of the unit:\r\n    'SCHEDULED'\r\n    'NON-SCHEDULED'\r\n    'SEMI-SCHEDULED'"))
    min_ramp_rate_up: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('min_ramp_rate_up', Numeric(6, 0), comment='MW/Min. Calculated Minimum Ramp Rate Up value accepted for Energy Offers or Bids with explanation'))
    min_ramp_rate_down: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('min_ramp_rate_down', Numeric(6, 0), comment='MW/Min. Calculated Minimum Ramp Rate Down value accepted for Energy Offers or Bids with explanation'))
    max_ramp_rate_up: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('max_ramp_rate_up', Numeric(6, 0), comment='Maximum ramp up rate for Unit (Mw/min) - from DUDetail table'))
    max_ramp_rate_down: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('max_ramp_rate_down', Numeric(6, 0), comment='Maximum ramp down rate for Unit (Mw/min) - from DUDetail table'))
    is_aggregated: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('is_aggregated', Numeric(1, 0), comment='Whether the DUID is classified as an "Aggregated Unit" under the rules. This impacts the Minimum Ramp Rate calculation'))
    dispatchsubtype: Optional[str] = Field(default=None, sa_column=Column('dispatchsubtype', String(20), comment='Additional information for DISPATCHTYPE. For DISPATCHTYPE = LOAD, subtype value is WDR for wholesale demand response units For DISPATCHTYPE = LOAD, subtype value is NULL for Scheduled Loads. For DISPATCHTYPE = GENERATOR type, subtype value is NULL.'))
    adg_id: Optional[str] = Field(default=None, sa_column=Column('adg_id', String(20), comment='Aggregate Dispatch Group. Group into which the DUID is aggregated for Conformance. Null if DUID not aggregated for Conformance'))
    load_minimum_energy_price: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_minimum_energy_price', Numeric(9, 2), comment='BDU only. Floored Offer/Bid Energy Price adjusted for TLF, DLF and MPF for energy imports'))
    load_maximum_energy_price: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_maximum_energy_price', Numeric(9, 2), comment='BDU only. Capped Offer/Bid Energy Price adjusted for TLF, DLF and VoLL for energy imports'))
    load_min_ramp_rate_up: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_min_ramp_rate_up', Numeric(6, 0), comment='BDU only. MW/Min. Calculated Minimum Ramp Rate Up value accepted for Energy Offers or Bids with explanation for energy imports'))
    load_min_ramp_rate_down: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_min_ramp_rate_down', Numeric(6, 0), comment='BDU only. MW/Min. Calculated Minimum Ramp Rate Down value accepted for Energy Offers or Bids with explanation for energy imports'))
    load_max_ramp_rate_up: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_max_ramp_rate_up', Numeric(6, 0), comment='BDU only. MW/Min. Registered Maximum Ramp Rate Up value accepted for Energy Offers or Bids for energy imports'))
    load_max_ramp_rate_down: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('load_max_ramp_rate_down', Numeric(6, 0), comment='BDU only. MW/Min. Registered Maximum Ramp Rate Down value accepted for Energy Offers or Bids for energy imports'))
    secondary_tlf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('secondary_tlf', Numeric(18, 8), comment='Used in Bidding, Dispatch and Settlements, only populated where Dual TLFs apply. For Bidding and Dispatch, the TLF for the generation component of a BDU, when null the TRANSMISSIONLOSSFACTOR is used for both the load and generation components. For Settlements, the secondary TLF is applied to all energy (load and generation) when the Net Energy Flow of the ConnectionPointID in the interval is positive (net generation).'))


