    regionid: str = Field(sa_column=Column('regionid', String(20), primary_key=True, comment='Unique RegionID'))
    bidtype: str = Field(sa_column=Column('bidtype', String(20), primary_key=True, comment='The type of regulation FCAS service [RAISEREG,LOWERREG]'))
    periodid: decimal.Decimal = Field(sa_column=Column('periodid', Numeric(3, 0), primary_key=True, comment='The Period ID (1 - 48) within the calendar day to which this usage factor applies'))
    usage_factor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('usage_factor', Numeric(8, 3), comment='The proportion of cleared regulation FCAS that is assumed to be used within a dispatch interval. Expressed as a fractional amount between 0 and 1'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='The last time the data has been changed/updated'))


