class FppConstraintFreqMeasure(SQLModel, table=True):
    __tablename__ = 'fpp_constraint_freq_measure'
    __table_args__ = (
        PrimaryKeyConstraint('interval_datetime', 'measurement_datetime', 'constraintid', 'versionno', name='fpp_constraint_freq_measure_pk'),
        {'comment': 'This report delivers the weighted 4 second frequency measure data '
                'for each constraint'}
    )

    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date and time of the trading interval (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time)'))
    measurement_datetime: datetime.datetime = Field(sa_column=Column('measurement_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date and time of the SCADA data (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time)'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(5, 0), primary_key=True, comment='Version (FPP run number from the FPP database)'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations)'))
    fm_raise_hz: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fm_raise_hz', Numeric(18, 8), comment='Calculated 4 second Frequency Measure in Hz for that constraint from the FPP database. Frequency Measure data is split across these two raise and lower columns in the following ways: >0 = Allocated to the FM_RAISE_HZ column <0 = Allocated to the FM_LOWER_HZ column 0 = To fill any gaps where the alternative column is not applicable (or no deviation from 50 Hz)'))
    fm_lower_hz: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fm_lower_hz', Numeric(18, 8), comment='Calculated 4 second Frequency Measure in Hz for that constraint from the FPP database. Frequency Measure data is split across these two raise and lower columns in the following ways: >0 = Allocated to the FM_RAISE_HZ column <0 = Allocated to the FM_LOWER_HZ column 0 = To fill any gaps where the alternative column is not applicable (or no deviation from 50 Hz)'))
    used_in_rcr_flag: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('used_in_rcr_flag', Numeric(5, 0), comment='Flag to indicate the result of the Frequency Measure alignment check between Mainland and Tasmania for global constraints. Supported values are: 0 = Not used in RCR calculation as the signs for the frequency measures between Mainland and Tasmania do not align 1 = Used in the RCR calculation as the signs for the frequency measures between Mainland and Tasmania do align in the case of global constraints. For non-global constraints this flag is set to 1'))
    correlation_flag: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('correlation_flag', Numeric(5, 0), comment='Flag to indicate the result of the Frequency Measure correlation check between regions in the same constraint. Supported values are: 0 = Frequency measures in this constraint are not correlated (e.g. system separation between two regions) 1 = Frequency measures in this constraint are correlated'))


class FppContributionFactor(SQLModel, table=True):
    __tablename__ = 'fpp_contribution_factor'
    __table_args__ = (
        PrimaryKeyConstraint('interval_datetime', 'constraintid', 'fpp_unitid', 'versionno', name='fpp_contribution_factor_pk'),
        {'comment': 'This report delivers the calculated contribution factor value for '
                'each 5 minute trading interval for each constraint and FPP unit'}
    )

    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date and time of the trading interval (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time)'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    fpp_unitid: str = Field(sa_column=Column('fpp_unitid', String(20), primary_key=True, comment='FPP Unit ID (registered DUID/ TNI)'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(5, 0), primary_key=True, comment='Version (FPP run number from the FPP database)'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations)'))
    contribution_factor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('contribution_factor', Numeric(18, 8), comment='Contribution Factor (the calculated contribution factor for the FPP unit and constraint ID for that trading interval) - for further details please see the FPP procedure document'))
    negative_contribution_factor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('negative_contribution_factor', Numeric(18, 8), comment='Negative Contribution Factor (the calculated negative contribution factor for the FPP unit and constraint ID for that trading interval) - for further details please see the FPP procedure document'))
    default_contribution_factor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('default_contribution_factor', Numeric(18, 8), comment='The Default Contribution Factor (the calculated default contribution factor based on historical performance for the FPP unit and constraint ID for that trading interval) that is effective for this trading interval, which joins back to FPP_FORECAST_DEFAULT_CF - for further details please see the FPP procedure document'))
    cf_reason_flag: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('cf_reason_flag', Numeric(5, 0), comment='The reason flag showing the decision matrix for the contribution factor (CF) Supported values are: 0 = CF is calculated based on good input data 1 = CF is 0 because it is not primary in the group 2 = CF is not for the DUID but for the whole group 4 = CF is calculated based on substitute performance 8 = CF is 0 because FM is unreliable. 16 = CF is 0 because more than 50 percent input is bad or not available.'))
    cf_abs_positive_perf_total: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('cf_abs_positive_perf_total', Numeric(18, 8), comment='The sum of absolute positive performance in MWHz for the combination of constraint / bid type (raise or lower). This is used as the denominator in normalising contribution factors (CF) where a units performance is positive. For further details please see the FPP procedure document. >0 = Performance was calculated for the units NULL = Performance for the units was unavailable'))
    cf_abs_negative_perf_total: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('cf_abs_negative_perf_total', Numeric(18, 8), comment='The sum of absolute negative performance in MWHz for the combination of constraint / bid type (raise or lower). This is used as the denominator in normalising contribution factors (CF) where a units performance is negative. For further details please see the FPP procedure document. >0 = Performance was calculated for the units NULL = Performance for the units was unavailable'))
    ncf_abs_negative_perf_total: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ncf_abs_negative_perf_total', Numeric(18, 8), comment='The sum of absolute negative performance in MWHz for the combination of constraint / bid type (raise or lower). This is used as the denominator in normalising negative contribution factors (NCF). For further details please see the FPP procedure document. >0 = Performance was calculated for the units NULL = Performance for the units was unavailable 0 = When NCF is zero (i.e. CF is positive), then this total will be represented as zero'))
    participantid: Optional[str] = Field(default=None, sa_column=Column('participantid', String(20), comment='Participant ID'))
    settlements_unitid: Optional[str] = Field(default=None, sa_column=Column('settlements_unitid', String(20), comment='The Settlements Unit ID (registered DUID / TNI) Note that this SETTLEMENTS_UNITID is what is sent and used by the Settlements system, and may be different from the FPP_UNITID for non- scheduled loads where the FPP_UNITID may be a descriptive key, whereas what will be sent to Settlements as the SETTLEMENTS_UNITID will be the TNI code.'))


class FppEstCost(SQLModel, table=True):
    __tablename__ = 'fpp_est_cost'
    __table_args__ = (
        PrimaryKeyConstraint('interval_datetime', 'constraintid', 'fpp_unitid', 'versionno', name='fpp_est_cost_pk'),
        {'comment': 'This report delivers the estimated cost for each FPP unit for '
                'each constraint for each 5 minute trading interval'}
    )

    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date and time of the trading interval (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time)'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    fpp_unitid: str = Field(sa_column=Column('fpp_unitid', String(20), primary_key=True, comment='FPP Unit ID (registered DUID / TNI)'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(10, 0), primary_key=True, comment='The version number. In most cases this version will be the FPP run number from the FPP database, however there are some cases (like a new pricing run of the constraint FCAS processor received by the FPP system) where the version number listed here will be the financial estimate run number from the FPP database (this number is a different sequence from the FPP run number because there is no recalculation of performance or contribution, just changes to pricing / p regulation hence only the financial estimation is performed).'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations)'))
    relevant_regions: Optional[str] = Field(default=None, sa_column=Column('relevant_regions', String(200), comment='Relevant regions (a comma separated list of the relevant regions for the constraint from FCAS data)'))
    fpp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fpp', Numeric(18, 8), comment='FPP in AUD (the financial estimate of frequency performance payment calculated for the constraint / bid type / unit). This value can be either positive (credit) or negative (debit). For details on the calculation, please see FPP procedure and supporting documentation.'))
    used_fcas: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('used_fcas', Numeric(18, 8), comment='Used recovery FCAS in AUD (the financial estimate of the recovery of used FCAS calculated for the constraint / bid type / unit). This value will be either 0 (nil), or a negative value (debit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))
    unused_fcas: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('unused_fcas', Numeric(18, 8), comment='Unused recovery FCAS in AUD (the financial estimate of the recovery of unused FCAS calculated for the constraint / bid type / unit). This value will be either 0 (nil), or a negative value (debit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))
    participantid: Optional[str] = Field(default=None, sa_column=Column('participantid', String(20), comment='Participant ID'))


