    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(10, 0), primary_key=True, comment='The version number. In most cases this version will be the FPP run number from the FPP database, however there are some cases (like a new pricing run of the constraint FCAS processor received by the FPP system) where the version number listed here will be the financial estimate run number from the FPP database (this number is a different sequence from the FPP run number because there is no recalculation of performance or contribution, just changes to pricing / p regulation hence only the financial estimation is performed).'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations)'))
    relevant_regions: Optional[str] = Field(default=None, sa_column=Column('relevant_regions', String(200), comment='Relevant regions (a comma separated list of the relevant regions for the constraint from FCAS data)'))
    fpp_payment_rate: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fpp_payment_rate', Numeric(18, 8), comment='The payment rate for FPP in AUD / MWHz (the denominator used is the sum of positive performance for the constraint calculated by contribution factor calculation). This value will be either 0 (nil), or a positive value (credit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))
    fpp_recovery_rate: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fpp_recovery_rate', Numeric(18, 8), comment='The recovery rate for FPP in AUD / MWHz (the denominator used is the absolute sum of negative performance for the constraint calculated by the contribution factor calculation). This value will be either 0 (nil), or a negative value (debit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))
    used_fcas_rate: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('used_fcas_rate', Numeric(18, 8), comment='The rate for used FCAS in AUD / MWHz (the denominator used is the absolute sum of negative performance for the constraint calculated by the negative contribution factor calculation). This value will be either 0 (nil), or a negative value (debit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))
    unused_fcas_rate: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('unused_fcas_rate', Numeric(18, 8), comment='The rate for unused FCAS in AUD / MWHz (the denominator used is the absolute sum of negative performance for the constraint calculated by the default contribution factor calculation). This value will be either 0 (nil), or a negative value (debit) only. For details on the calculation, please see FPP procedure and supporting documentation.'))


