class FppFcasSummary(SQLModel, table=True):
    __tablename__ = 'fpp_fcas_summary'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runno', 'interval_datetime', 'constraintid', 'versionno', name='fpp_fcas_summary_pk'),
        {'comment': 'This report delivers a summary of FCAS requirements as used by '
                'the FPP calculation (i.e. only RAISEREG / LOWERREG bid types)'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The run date and time of the dispatch case that was the trigger for the constraint FCAS processor execution'))
    runno: decimal.Decimal = Field(sa_column=Column('runno', Numeric(5, 0), primary_key=True, comment='The dispatch case run number that was the trigger for the constraint FCAS processor execution'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date and time of the trading interval (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time)'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(10, 0), primary_key=True, comment='The version number. In most cases this version will be the FPP run number from the FPP database, however there are some cases (like a new pricing run of the constraint FCAS processor received by the FPP system) where the version number listed here will be the financial estimate run number from the FPP database (this number is a different sequence from the FPP run number because there is no recalculation of performance or contribution, just changes to pricing / p regulation hence only the financial estimation is performed).'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations, i.e. RAISEREG or LOWERREG)'))
    relevant_regions: Optional[str] = Field(default=None, sa_column=Column('relevant_regions', String(200), comment='Relevant regions (a comma separated list of the relevant regions for the constraint from FCAS data)'))
    regulation_mw: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('regulation_mw', Numeric(18, 8), comment='Enabled regulation MW used in the FPP calculation (from FPP database)'))
    constraint_marginal_value: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constraint_marginal_value', Numeric(18, 8), comment='Marginal value in AUD/MW per hour related to the constraint (from FCAS data used for FPP calculations)'))
    p_regulation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('p_regulation', Numeric(18, 8), comment='P regulation value in AUD/MW per hour related to the constraint (from FCAS data used for FPP calculations also known as adjusted marginal value)'))
    base_cost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('base_cost', Numeric(18, 8), comment='Base cost in AUD related to the constraint (from FCAS data used for FPP calculations)'))
    tsfcas: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('tsfcas', Numeric(18, 8), comment='TSFCAS in AUD related to the constraint (FCAS recovery amount related to the constraint also known as adjusted cost)'))
    total_fpp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('total_fpp', Numeric(18, 8), comment='Total amount of FPP in AUD changing hands related to the constraint (note that this is not the sum of FPP)'))
    rcr: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rcr', Numeric(18, 5), comment='RCR MW (the calculated requirement for corrective response from FPP database). Note that this is a join back to the FPP_RCR table.'))
    usage: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('usage', Numeric(18, 8), comment='Usage (calculation of the proportion of regulation FCAS that was calculated to be used). Note that this is a join back to the FPP_USAGE table.'))


class FppForecastDefaultCf(SQLModel, table=True):
    __tablename__ = 'fpp_forecast_default_cf'
    __table_args__ = (
        PrimaryKeyConstraint('fpp_unitid', 'constraintid', 'effective_start_datetime', 'effective_end_datetime', 'versionno', name='fpp_forecast_default_cf_pk'),
        {'comment': 'This report delivers the forecast default contribution factors '
                '(DCF) effective for a billing period (aligned to the settlement '
                'week)'}
    )

    fpp_unitid: str = Field(sa_column=Column('fpp_unitid', String(20), primary_key=True, comment='FPP Unit ID (registered DUID/ TNI)'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint ID (binding constraint ID from FCAS data used in FPP calculations)'))
    effective_start_datetime: datetime.datetime = Field(sa_column=Column('effective_start_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Effective period start date and time (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time) of the effective period for this default contribution factor related to the combination of FPP unit ID / constraint. This is the billing period over which these default contribution factors will be effective / applied. In most cases this will align to the settlement week, however there are some cases (like a new constraint) where the effective start date will be prorated to align with the change.'))
    effective_end_datetime: datetime.datetime = Field(sa_column=Column('effective_end_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Effective period end date and time (DD/MM/YYYY HH24:MI:SS) fixed to the UTC+10 time zone (NEM time) of the effective period for this default contribution factor related to the combination of FPP unit ID / constraint. This is the billing period over which these default contribution factors will be effective / applied. Effective end date will align with the end of a settlement week.'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(10, 0), primary_key=True, comment='The version number. In most cases this version will be the historical performance calculation run number from the FPP database (which is different from the FPP run number), however there are some cases (like a new constraint) where the version number listed here will be the FPP run number from the FPP database (this will be where the effective start date time will be prorated to align with the detection of this change).'))
    bidtype: Optional[str] = Field(default=None, sa_column=Column('bidtype', String(10), comment='Bid type (the bid type saved in relation to constraint ID from FCAS data used in FPP calculations)'))
    regionid: Optional[str] = Field(default=None, sa_column=Column('regionid', String(20), comment='Region ID of the frequency deviation / frequency measure'))
    default_contribution_factor: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('default_contribution_factor', Numeric(18, 8), comment='Calculated default contribution factor from the historical performance period. For further details please see the FPP procedure document.'))
    dcf_reason_flag: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('dcf_reason_flag', Numeric(5, 0), comment='The reason flag showing the decision matrix for the default contribution factor (DCF)'))
    dcf_abs_negative_perf_total: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('dcf_abs_negative_perf_total', Numeric(18, 8), comment='The sum of absolute negative performance in MWHz for the combination of constraint (raise or lower). This is used as the denominator in normalising default contribution factors (DCF) as the historical performance is always negative for DCF. For further details please see the FPP procedure document. >0 = Performance was calculated for the units NULL = Performance for the units was unavailable'))
    settlements_unitid: Optional[str] = Field(default=None, sa_column=Column('settlements_unitid', String(20), comment='The Settlements Unit ID (registered DUID / TNI) Note that this SETTLEMENTS_UNITID is what is sent and used by the Settlements system, and may be different from the FPP_UNITID for non- scheduled loads where the FPP_UNITID may be a descriptive key, whereas what will be sent to Settlements as the SETTLEMENTS_UNITID will be the TNI code.'))


