    constraintvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constraintvalue', Numeric(16, 6), comment='the RHS value used if there is no dynamic RHS defined in GenericConstraintRHS'))
    description: Optional[str] = Field(default=None, sa_column=Column('description', String(256), comment='Detail of the plant that is not in service'))
    status: Optional[str] = Field(default=None, sa_column=Column('status', String(8), comment='Not used'))
    genericconstraintweight: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('genericconstraintweight', Numeric(16, 6), comment='The constraint violation penalty factor'))
