    dynamicrhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('dynamicrhs', Numeric(15, 5), comment='Not used'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))
    dispatch: Optional[str] = Field(default=None, sa_column=Column('dispatch', String(1), comment='Flag: constraint RHS used for Dispatch? 1-used, 0-not used'))
