    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(3, 0), primary_key=True))
    participantid: str = Field(sa_column=Column('participantid', String(10), primary_key=True))
    filename: str = Field(sa_column=Column('filename', String(40), primary_key=True))
    authoriseddate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('authoriseddate', TIMESTAMP(precision=0)))
    authorisedby: Optional[str] = Field(default=None, sa_column=Column('authorisedby', String(15)))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0)))


