class MtpasaCaseSet(SQLModel, table=True):
    __tablename__ = 'mtpasa_case_set'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'run_no', name='mtpasa_case_set_pk'),
        Index('mtpasa_case_set_lcx', 'lastchanged'),
        {'comment': 'MTPASA_CASE_SET is obsolete from 2005 End of Year Release. The '
                'RUNTYPE added to the primary key of the detail tables for MTPASA '
                'allows for the different types of runs for each case.\r\n'
                'MTPASA_CASE_SET allows a MT PASA scenario to be linked across '
                'runs.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date processing of the run begins. Generated from the solution file CASEID.'))
    run_no: decimal.Decimal = Field(sa_column=Column('run_no', Numeric(3, 0), primary_key=True, comment='Unique run id. Generated from the solution file CASEID.'))
    casesetid: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('casesetid', Numeric(3, 0), comment='Unique id to link a set of cases run from the same inputs'))
    runtypeid: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('runtypeid', Numeric(1, 0), comment='Unique id for type of run, being either'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Date the solution was loaded'))


class MtpasaCaseresult(SQLModel, table=True):
    __tablename__ = 'mtpasa_caseresult'
