class MtpasaCasesolution(SQLModel, table=True):
    __tablename__ = 'mtpasa_casesolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'run_no', name='mtpasa_casesolution_pk'),
        Index('mtpasa_casesolution_lcx', 'lastchanged'),
        {'comment': 'MTPASA_CASESOLUTION is obsolete from 2017 End of Year DM4.27 '
                'Release. \r\n'
                'MTPASA_CASESOLUTION holds one record for each entire solution.\r\n'
                'Change Notice 379 announced the replacement of the MT PASA data '
                'model so all MTPASAxxx tables become obsolete, replaced by '
                'MTPASA_xxx tables.'}
    )

