    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date processing of the run begins.'))
    run_no: decimal.Decimal = Field(sa_column=Column('run_no', Numeric(4, 0), primary_key=True, comment='Unique run id.'))
