    totalintermittentgen50: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalintermittentgen50', Numeric(12, 2), comment='The 50th percentile for intermittent generation, across iterations and reference years (MW)'))
    totalintermittentgen10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalintermittentgen10', Numeric(12, 2), comment='The 10th percentile for intermittent generation, across iterations and reference years (MW)'))
