class MtpasaRegionsolution(SQLModel, table=True):
    __tablename__ = 'mtpasa_regionsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'run_no', 'runtype', 'energyblock', 'day', 'ldcblock', 'regionid', name='mtpasa_regionsolution_pk'),
        Index('mtpasa_regionsolution_ndx2', 'lastchanged'),
        {'comment': 'MTPASA_CASESOLUTION is obsolete from 2017 End of Year DM4.27 '
                'Release. \r\n'
                'The MTPASA_REGIONSOLUTION table shows the results of the regional '
                'capacity, maximum surplus reserve and maximum spare capacity '
                'evaluations for each day and ldcblock of the study.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Date processing of the run begins'))
    run_no: decimal.Decimal = Field(sa_column=Column('run_no', Numeric(3, 0), primary_key=True, comment='Unique run id. Generated from the solution file caseid'))
    energyblock: datetime.datetime = Field(sa_column=Column('energyblock', TIMESTAMP(precision=0), primary_key=True, comment='Sunday at start of the week for this solutions energy block. Generated from the solution file energy block'))
    day: datetime.datetime = Field(sa_column=Column('day', TIMESTAMP(precision=0), primary_key=True, comment='Day this solution is for. Generated from the solution file periodid'))
    ldcblock: decimal.Decimal = Field(sa_column=Column('ldcblock', Numeric(3, 0), primary_key=True, comment='LDC block this solution is for. Generated from the solution file periodid'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='The unique region identifier'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run.  Values are RELIABILITY_LRC and OUTAGE_LRC'))
    demand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand10', Numeric(12, 2), comment='Input value for 10% probability demand'))
    reservereq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservereq', Numeric(12, 2), comment='Not used from 21/05/2010. Prior to 21/05/2010: Input reserve requirement'))
    capacityreq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityreq', Numeric(12, 2), comment='Not used from 21/05/2010. Prior to 21/05/2010: CA Demand + Reserve Requirement'))
    energyreqdemand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energyreqdemand10', Numeric(12, 2), comment='Sum of: (Region Period Demand - given Demand10)/PeriodLength(sum by Energy Block, entered in first period of energy block, GWh)'))
    unconstrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('unconstrainedcapacity', Numeric(12, 0), comment='Region energy unconstrained MW capacity subject to network security constraints'))
    constrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constrainedcapacity', Numeric(12, 0), comment='Region energy constrained MW capacity subject to energy and network security constraints'))
    netinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('netinterchangeunderscarcity', Numeric(12, 2), comment='Calculated in capacity adequacy evaluation: Export if > 0, Import if < 0.'))
    surpluscapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surpluscapacity', Numeric(12, 2), comment='Regional surplus capacity MW, +/- values indicate surplus/deficit capacity'))
    surplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surplusreserve', Numeric(12, 2), comment='Not used from 21/05/2010. Prior to 21/05/2010: Regional reserve surplus. +/-0 values indicate surplus/deficit reserve'))
    reservecondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservecondition', Numeric(1, 0), comment='The regional reserve condition: 0 = Adequate, 1 = LRC'))
    maxsurplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsurplusreserve', Numeric(12, 2), comment='The Maximum generation (MW) that could be withdrawn from this region without incurring a Low Reserve Condition.'))
    maxsparecapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsparecapacity', Numeric(12, 2), comment='The Maximum Spare Capacity evaluated for this region in this period. Calculated for each region in turn'))
    lorcondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lorcondition', Numeric(1, 0), comment='The LOR Condition determined from the Maximum Spare Capacity value: 0 = no condition, 1 = LOR1 condition, 2 = LOR2 condition, 3 = LOR3 condition'))
    aggregatecapacityavailable: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatecapacityavailable', Numeric(12, 2), comment='Sum of  MAXAVAIL quantities offered by all Scheduled Generators in a given Region for a given PERIODID.'))
    aggregatescheduledload: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatescheduledload', Numeric(12, 2), comment='Sum of  MAXAVAIL quantities bid by of all Scheduled Loads in a given Region for a given PERIODID.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Date the solution was loaded'))
    aggregatepasaavailability: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatepasaavailability', Numeric(12, 0), comment='Sum of  PASAAVAILABILITY quantities offered by all Scheduled Generators in a given Region for a given PERIODID.'))
    calculatedlor1level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor1level', Numeric(16, 6), comment='Region Reserve Level for LOR1 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    calculatedlor2level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor2level', Numeric(16, 6), comment='Region Reserve Level for LOR2 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    msrnetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('msrnetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the MSR assessment'))
    lornetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lornetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the LOR assessment'))
