    marginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('marginalvalue', Numeric(16, 6), comment='Marginal Value of the Reserve Requirement Constraint. A non-zero value indicates that the reserve requirement is binding.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Timestamp the record was last modified.'))


