    outageid: decimal.Decimal = Field(sa_column=Column('outageid', Numeric(15, 0), primary_key=True, comment='ID uniquely identifying the outage'))
    substationid: str = Field(sa_column=Column('substationid', String(30), primary_key=True, comment='The substation this equipment is located at'))
    equipmenttype: str = Field(sa_column=Column('equipmenttype', String(10), primary_key=True, comment='The type of equipment. Valid values are:\r\nLINE = Line\r\nTRANS = Transformer\r\nCB = Circuit breaker\r\nISOL = Isolator\r\nCAP = Capacitor\r\nREAC = Reactor\r\nUNIT = Unit'))
    equipmentid: str = Field(sa_column=Column('equipmentid', String(30), primary_key=True, comment='A unique identifier for this equipment at this substation, and based on its type'))
    starttime: datetime.datetime = Field(sa_column=Column('starttime', TIMESTAMP(precision=0), primary_key=True, comment='The planned starting date and time of the outage'))
    elementid: decimal.Decimal = Field(sa_column=Column('elementid', Numeric(15, 0), primary_key=True, comment='Equipment element id'))
    endtime: Optional[datetime.datetime] = Field(default=None, sa_column=Column('endtime', TIMESTAMP(precision=0), comment='The planned ending date and time of the outage'))
    submitteddate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('submitteddate', TIMESTAMP(precision=0), comment='The date and time this outage was first submitted'))
    outagestatuscode: Optional[str] = Field(default=None, sa_column=Column('outagestatuscode', String(10), comment='A code representing the status of the outage.\r\nThe OUTAGESTATUSCODE table will store a detailed description of each code.'))
    resubmitreason: Optional[str] = Field(default=None, sa_column=Column('resubmitreason', String(50), comment='Changes to an outage key details may require the outage to be resubmitted.\r\nA new outage id will then be allocated and the outage will be reassessed.\r\nThis field will detail the reason for the change.'))
    resubmitoutageid: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('resubmitoutageid', Numeric(15, 0), comment='The new outage id created from a resubmit.'))
    recalltimeday: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('recalltimeday', Numeric(10, 0), comment='The recall time in minutes during the day'))
    recalltimenight: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('recalltimenight', Numeric(10, 0), comment='The recall time in minutes during the night'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=3), comment='The time that this record was last changed'))
    reason: Optional[str] = Field(default=None, sa_column=Column('reason', String(100), comment='The reason provided by the asset owner for this outage'))
    issecondary: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('issecondary', Numeric(1, 0), comment='1 = The outage is for a secondary piece of equipment that has an associated constraint set. The transmission equipment is still in service. 0 = The outage is for the transmission equipment'))
