class NetworkStaticrating(SQLModel, table=True):
    __tablename__ = 'network_staticrating'
    __table_args__ = (
        PrimaryKeyConstraint('substationid', 'equipmenttype', 'equipmentid', 'ratinglevel', 'applicationid', 'validfrom', name='pk_network_staticrating'),
        Index('network_staticrating_lcx', 'lastchanged'),
        {'comment': 'NETWORK_STATICRATING lists the static rating values that will '
                'apply for a Rating Application ID.\r\n'
                'This data does not provide information for when the rating '
                'actually applies in the NEM. This is dependent on the Rating '
                'Application definition.\r\n'
                'For information on the Rating Applications please refer to the '
                'information published on the AEMO website under the topic '
                '"Transmission Equipment Ratings". The Rating Applications are '
                'referred to as Alternate Value Application Ratings.\r\n'
                'Ratings that normally use dynamic values will also have static '
                'rating values defined. These are used as a fallback if the '
                'dynamic rating fails.'}
    )

    substationid: str = Field(sa_column=Column('substationid', String(30), primary_key=True, comment='The substation the equipment is located at'))
    equipmenttype: str = Field(sa_column=Column('equipmenttype', String(10), primary_key=True, comment='The type of equipment. Valid values are:\r\nLINE = Line\r\nTRANS = Transformer\r\nCB = Circuit breaker\r\nISOL = Isolator\r\nCAP = Capacitor\r\nREAC = Reactor\r\nUNIT = Unit'))
    equipmentid: str = Field(sa_column=Column('equipmentid', String(30), primary_key=True, comment='A unique identifier for this type of equipment at this substation'))
    ratinglevel: str = Field(sa_column=Column('ratinglevel', String(10), primary_key=True, comment='The rating level of the value used, one of:\r\nNORM = Continuous rating value. Applied under pre-contingent conditions.\r\nEMER = Continuous rating value. Applied under pre-contingent conditions\r\nLDSH = Load Shedding'))
    applicationid: str = Field(sa_column=Column('applicationid', String(20), primary_key=True, comment='The applicationid which defines the application timeframes of this rating.'))
    validfrom: datetime.datetime = Field(sa_column=Column('validfrom', TIMESTAMP(precision=0), primary_key=True, comment='The date that this record is applies from (inclusive)'))
    validto: Optional[datetime.datetime] = Field(default=None, sa_column=Column('validto', TIMESTAMP(precision=0), comment='The date that this record applies until (exclusive)'))
    ratingvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ratingvalue', Numeric(16, 6), comment='The rating value in MVA that applies. This may be positive or negative depending on which side of the nominal MW flow direction the rating value applies.\r\nFlow into a transmission device is positive, flow out of the device is negative.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='The time that this record was last changed.'))


