class P5minCasesolution(SQLModel, table=True):
    __tablename__ = 'p5min_casesolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', name='p5min_casesolution_pk'),
        Index('p5min_casesolution_lcx', 'lastchanged'),
        {'comment': 'The five-minute predispatch (P5Min) is a MMS system providing '
                'projected dispatch for 12 Dispatch cycles (one hour). The '
                '5-minute Predispatch cycle runs every 5-minutes to produce a '
                'dispatch and pricing schedule to a 5-minute resolution covering '
                'the next hour, a total of twelve periods.\r\n'
                'P5MIN_CASESOLUTION shows one record containing results pertaining '
                'to the entire solution.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    startinterval_datetime: Optional[str] = Field(default=None, sa_column=Column('startinterval_datetime', String(20), comment='Date and Time of first interval in study'))
    totalobjective: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalobjective', Numeric(27, 10), comment='The Objective function from the LP'))
    nonphysicallosses: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('nonphysicallosses', Numeric(1, 0), comment='Flag to indicate non-physical losses occurred in this study'))
    totalareagenviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalareagenviolation', Numeric(15, 5), comment='Sum of Regional Energy balance violations'))
    totalinterconnectorviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalinterconnectorviolation', Numeric(15, 5), comment='Sum of Interconnector violations of standing data limits'))
    totalgenericviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalgenericviolation', Numeric(15, 5), comment='Sum of Generic Constraint violations'))
    totalramprateviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalramprateviolation', Numeric(15, 5), comment='Sum of Unit Ramp Rate violations'))
    totalunitmwcapacityviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalunitmwcapacityviolation', Numeric(15, 5), comment='Sum of unit capacity violations'))
    total5minviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('total5minviolation', Numeric(15, 5), comment='Sum of regional 5 min FCAS violations'))
    totalregviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalregviolation', Numeric(15, 5), comment='Sum of regional regulation FCAS violations'))
    total6secviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('total6secviolation', Numeric(15, 5), comment='Sum of regional 6 sec FCAS violations'))
    total60secviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('total60secviolation', Numeric(15, 5), comment='Sum of regional 60 sec FCAS violations'))
    totalenergyconstrviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalenergyconstrviolation', Numeric(15, 5), comment='Sum of unit energy constrained violations'))
    totalenergyofferviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalenergyofferviolation', Numeric(15, 5), comment='Sum of unit offer violations'))
    totalasprofileviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalasprofileviolation', Numeric(15, 5), comment='Sum of unit FCAS profile offer violations'))
    totalfaststartviolation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalfaststartviolation', Numeric(15, 5), comment='Sum of unit Fast start profile violations'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last changed date and time of this record'))
    intervention: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('intervention', Numeric(2, 0), comment='Flag to indicate if this Predispatch case includes an intervention pricing run: 0 = case does not include an intervention pricing run, 1 = case does include an intervention pricing run. This field has a default value of 0 and is not nullable'))


class P5minConstraintsolution(SQLModel, table=True):
    __tablename__ = 'p5min_constraintsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'constraintid', 'interval_datetime', name='p5min_constraintsolution_pk'),
        Index('p5min_constraintsolution_lcx', 'lastchanged'),
        {'comment': 'The Five-Minute Pre-Dispatch (P5Min) is a MMS system providing '
                'projected dispatch for 12 Dispatch cycles (one hour). The '
                'Five-Minute Pre-dispatch cycle runs every 5-minutes to produce a '
                'dispatch and pricing schedule to a 5-minute resolution covering '
                'the next hour, a total of twelve periods.\r\n'
                'P5MIN_CONSTRAINTSOLUTION shows binding and violated constraint '
                'results from the capacity evaluation, including the RHS value.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint identifier (synonymous with GenConID)'))
    rhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rhs', Numeric(15, 5), comment='Right Hand Side value in the capacity evaluation'))
    marginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('marginalvalue', Numeric(15, 5), comment='Marginal cost of constraint (>0 if binding)'))
    violationdegree: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('violationdegree', Numeric(15, 5), comment='Amount of Violation (>0 if  violating)'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))
    duid: Optional[str] = Field(default=None, sa_column=Column('duid', String(20), comment='DUID to which the Constraint is confidential. Null denotes non-confidential'))
    genconid_effectivedate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('genconid_effectivedate', TIMESTAMP(precision=0), comment='Effective date of the Generic Constraint (ConstraintID). This field is used to track the version of this generic constraint applied in this dispatch interval'))
    genconid_versionno: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('genconid_versionno', Numeric(22, 0), comment='Version number of the Generic Constraint (ConstraintID). This field is used to track the version of this generic constraint applied in this dispatch interval'))
    lhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lhs', Numeric(15, 5), comment='Aggregation of the constraints LHS term solution values'))
    intervention: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('intervention', Numeric(2, 0), comment='Flag to indicate if this result set was sourced from the pricing run (INTERVENTION=0) or the physical run(INTERVENTION=1). In the event there is not intervention in the market, both pricing and physical runs correspond to INTERVENTION=0)'))


class P5minFcasReqConstraint(SQLModel, table=True):
    __tablename__ = 'p5min_fcas_req_constraint'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runno', 'interval_datetime', 'constraintid', 'regionid', 'bidtype', name='p5min_fcas_req_constraint_pk'),
        {'comment': 'The constraint level FCAS cost / price details for constraint '
                'FCAS processor runs. This enhanced output table format is '
                'established for the constraint FCAS processor release required '
                'for the Frequency Performance Payments (FPP) release. This '
                'enhanced output is hierarchical in nature, with the parent '
                '*_FCAS_REQ_RUN table holding the details about the triggering '
                'case run and time, and the child *_FCAS_REQ_CONSTRAINT table '
                'holding the constraint level details of FCAS costs / prices.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The run date and time of the 5 minute predispatch case that triggers the constraint FCAS processor run'))
    runno: decimal.Decimal = Field(sa_column=Column('runno', Numeric(5, 0), primary_key=True, comment='The 5 minute predispatch case run number that has triggers the constraint FCAS processor run'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The 5 minute interval date and time of the 5 minute predispatch interval that was processed by the constraint FCAS processor'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='ConstraintID join to table GenConData'))
    regionid: str = Field(sa_column=Column('regionid', String(20), primary_key=True, comment='Region identifier'))
    bidtype: str = Field(sa_column=Column('bidtype', String(10), primary_key=True, comment='DUID offered type'))
    lhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lhs', Numeric(15, 5), comment='Constraints summed LHS - aggregate LHS Solution values from the physical run from the P5MIN_CONSTRAINTSOLUTION table'))
    rhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rhs', Numeric(15, 5), comment='Constraints RHS value used in the solution - may be either dynamic (calculated) or static from the physical run from the P5MIN_CONSTRAINTSOLUTION table'))
    marginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('marginalvalue', Numeric(15, 5), comment='Shadow price of constraint from the P5MIN_CONSTRAINTSOLUTION table from the physical run.'))
    rrp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rrp', Numeric(15, 5), comment='Bid type prices for the region coming from the pricing run of the P5MIN_REGIONSOLUTION table'))
    regional_enablement: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('regional_enablement', Numeric(15, 5), comment='The dispatched MW for the bid type inside the region from the physical run of the P5MIN_REGIONSOLUTION table'))
    constraint_enablement: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constraint_enablement', Numeric(15, 5), comment='MW enabled for this bid type within the constraint'))
    region_base_cost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('region_base_cost', Numeric(18, 8), comment='The regional payment allocated to the constraint for the interval pro- rated based on marginal value ratios over the binding constraints for that service in that region (this is an intermediate calculation to get to the base cost)'))
    base_cost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('base_cost', Numeric(18, 8), comment='The base cost of the constraint, before the regulation/contingency split'))
    adjusted_cost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('adjusted_cost', Numeric(18, 8), comment='The adjusted cost of the constraint for this service, after the regulation/contingency split'))
    p_regulation: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('p_regulation', Numeric(18, 8), comment='The adjusted marginal value of the constraint for FPP recovery (blank for constraints without REG terms)'))


