class P5minRegionsolution(SQLModel, table=True):
    __tablename__ = 'p5min_regionsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'regionid', 'interval_datetime', name='p5min_regionsolution_pk'),
        Index('p5min_regionsolution_lcx', 'lastchanged'),
        {'comment': 'The five-minute predispatch (P5Min) is a MMS system providing '
                'projected dispatch for 12 Dispatch cycles (one hour). The '
                '5-minute Predispatch cycle runs every 5-minutes to produce a '
                'dispatch and pricing schedule to a 5-minute resolution covering '
                'the next hour, a total of twelve periods.\r\n'
                'P5MIN_REGIONSOLUTION shows the results of the regional capacity, '
                'maximum surplus reserve and maximum spare capacity evaluations '
                'for each period of the study.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region Identifier'))
    rrp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rrp', Numeric(15, 5), comment='Region Reference Price (Energy)'))
    rop: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rop', Numeric(15, 5), comment='Region Override Price (Energy)'))
