class P5minScenariodemand(SQLModel, table=True):
    __tablename__ = 'p5min_scenariodemand'
    __table_args__ = (
        PrimaryKeyConstraint('effectivedate', 'version_datetime', 'regionid', 'scenario', name='p5min_scenariodemand_pk'),
        {'comment': 'The P5Min scenario MW offsets'}
    )

    effectivedate: datetime.datetime = Field(sa_column=Column('effectivedate', TIMESTAMP(precision=0), primary_key=True, comment='The effective date of this set of scenarios'))
    version_datetime: datetime.datetime = Field(sa_column=Column('version_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The version of this set of scenarios'))
    scenario: decimal.Decimal = Field(sa_column=Column('scenario', Numeric(2, 0), primary_key=True, comment='The scenario identifier'))
    regionid: str = Field(sa_column=Column('regionid', String(20), primary_key=True, comment='The region to which to apply the deltaMW for this SCENARIO'))
    deltamw: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('deltamw', Numeric(4, 0), comment='The MW offset to apply to region total demand for this SCENARIO'))


