class P5minUnitsolution(SQLModel, table=True):
    __tablename__ = 'p5min_unitsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'duid', 'interval_datetime', name='p5min_unitsolution_pk'),
        Index('p5min_unitsolution_lcx', 'lastchanged'),
        {'comment': 'The five-minute predispatch (P5Min) is a MMS system providing '
                'projected dispatch for 12 Dispatch cycles (one hour). The '
                '5-minute Predispatch cycle runs every 5-minutes to produce a '
                'dispatch and pricing schedule to a 5-minute resolution covering '
                'the next hour, a total of twelve periods.\r\n'
                'P5MIN_UNITSOLUTION shows the Unit results from the capacity '
                'evaluations for each period of the study.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    duid: str = Field(sa_column=Column('duid', String(10), primary_key=True, comment='Dispatchable unit identifier'))
    connectionpointid: Optional[str] = Field(default=None, sa_column=Column('connectionpointid', String(12), comment='Connection point identifier for DUID'))
    tradetype: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('tradetype', Numeric(2, 0), comment='Generator or Load'))
    agcstatus: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('agcstatus', Numeric(2, 0), comment='AGC Status from EMS: 1 = on, 0 = off'))
    initialmw: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('initialmw', Numeric(15, 5), comment='Initial MW at start of period. For periods subsequent to the first period of a P5MIN run, this value represents the cleared target for the previous period of that P5MIN run. Negative values when Bi-directional Unit start from importing power, otherwise positive.'))
    totalcleared: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalcleared', Numeric(15, 5), comment='Target MW for end of period. Negative values when Bi-directional Unit is importing power, otherwise positive.'))
