class PdpasaCasesolution(SQLModel, table=True):
    __tablename__ = 'pdpasa_casesolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', name='pdpasa_casesolution_pk'),
        Index('pdpasa_casesolution_lcx', 'lastchanged'),
        {'comment': 'The top-level table identifying a PDPASA case, reporting options '
                'applied in the case and summary results'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Case identifier by the time the case was run'))
    pasaversion: Optional[str] = Field(default=None, sa_column=Column('pasaversion', String(10), comment='Version of the PASA solver used to solve this case'))
    reservecondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservecondition', Numeric(1, 0), comment='Low Reserve Condition (LRC) flag for the case (1 - LRC in the case, 0 - No LRCs in the case) for capacity run'))
    lorcondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lorcondition', Numeric(1, 0), comment='Lack of Reserve Condition (LOR) flag for the case indicates the most severe condition in the case  (3 = LOR3, 2 = LOR2, 1 = LOR1, 0 = No LOR)'))
    capacityobjfunction: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityobjfunction', Numeric(12, 3), comment='Objective Function from the Capacity Adequacy run'))
    capacityoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityoption', Numeric(12, 3), comment='Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for capacity adequacy (LRC) assessment. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE.'))
    maxsurplusreserveoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsurplusreserveoption', Numeric(12, 3), comment='Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for assessment of Maximum surplus Reserve. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE'))
    maxsparecapacityoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsparecapacityoption', Numeric(12, 3), comment='Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for assessment of Maximum Spare Capacity. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE'))
    interconnectorflowpenalty: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('interconnectorflowpenalty', Numeric(12, 3), comment='The penalty for non-zero interconnector flow'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Date and time the record was created or modified'))
    reliabilitylrcdemandoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reliabilitylrcdemandoption', Numeric(12, 3), comment='Specifies the Probability of Exceedence (POE) demand forecast for Reliability LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)'))
    outagelrcdemandoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('outagelrcdemandoption', Numeric(12, 3), comment='Specifies the Probability of Exceedence (POE) demand forecast for outage LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)'))
    lordemandoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lordemandoption', Numeric(12, 3), comment='Specifies the Probability of Exceedence (POE) demand forecast for LOR assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)'))
    reliabilitylrccapacityoption: Optional[str] = Field(default=None, sa_column=Column('reliabilitylrccapacityoption', String(10), comment='Generation Availability to be used in Reliability LRC run (either PASA or MARKET)'))
    outagelrccapacityoption: Optional[str] = Field(default=None, sa_column=Column('outagelrccapacityoption', String(10), comment='Generation Availability to be used in Outage LRC run (either PASA or MARKET)'))
    lorcapacityoption: Optional[str] = Field(default=None, sa_column=Column('lorcapacityoption', String(10), comment='Generation Availability to be used in LOR run (either PASA or MARKET)'))
    loruigfoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('loruigfoption', Numeric(3, 0), comment='UIGF POE forecast availability used for this option'))
    reliabilitylrcuigfoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reliabilitylrcuigfoption', Numeric(3, 0), comment='UIGF POE forecast availability used for this option'))
    outagelrcuigfoption: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('outagelrcuigfoption', Numeric(3, 0), comment='UIGF POE forecast availability used for this option'))


class PdpasaConstraintsolution(SQLModel, table=True):
    __tablename__ = 'pdpasa_constraintsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runtype', 'interval_datetime', 'constraintid', 'studyregionid', name='pdpasa_constraintsolution_pk'),
        {'comment': 'PDPASA_CONSTRAINTSOLUTION shows binding and violated constraint '
                'results from the capacity evaluation, including the RHS value.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint identifier (synonymous with GenConID)'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR.'))
    studyregionid: str = Field(sa_column=Column('studyregionid', String(20), primary_key=True, server_default=text("'MARKET'::character varying"), comment='Primary Region for LP Solve (or MARKET if none).'))
    capacityrhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityrhs', Numeric(12, 2), comment='The RHS value in the capacity evaluation.'))
    capacitymarginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacitymarginalvalue', Numeric(12, 2), comment='Capacity adequacy assessment marginal value, 0 if not binding'))
    capacityviolationdegree: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityviolationdegree', Numeric(12, 2), comment='Capacity adequacy assessment violation degree for generic constraint; 0 if not violating'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last changed date of this record'))


class PdpasaInterconnectorsoln(SQLModel, table=True):
    __tablename__ = 'pdpasa_interconnectorsoln'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runtype', 'interval_datetime', 'interconnectorid', 'studyregionid', name='pdpasa_interconnectorsoln_pk'),
        {'comment': 'PDPASA_INTERCONNECTORSOLN shows the results of the capacity '
                'evaluation for Interconnectors, including the calculated limits '
                'for the interval.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    interconnectorid: str = Field(sa_column=Column('interconnectorid', String(10), primary_key=True, comment='Interconnector Identifier'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR.'))
    studyregionid: str = Field(sa_column=Column('studyregionid', String(20), primary_key=True, server_default=text("'MARKET'::character varying"), comment='Primary Region for LP Solve (or MARKET if none).'))
    capacitymwflow: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacitymwflow', Numeric(12, 2), comment='Interconnector loading level (MW) that can be reached in case of capacity scarcity in neighbouring regions subject to network and energy constraints'))
    capacitymarginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacitymarginalvalue', Numeric(12, 2), comment='Capacity adequacy assessment marginal value, 0 if not binding'))
    capacityviolationdegree: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityviolationdegree', Numeric(12, 2), comment='Capacity adequacy assessment violation degree for interconnector capacity; 0 if not violating'))
    calculatedexportlimit: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedexportlimit', Numeric(12, 2), comment='Calculated Interconnector limit of exporting energy on the basis of invoked constraints and static interconnector export limit'))
    calculatedimportlimit: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedimportlimit', Numeric(12, 2), comment='Calculated Interconnector limit of importing energy on the basis of invoked constraints and static interconnector import limit. Note unlike the input interconnector import limit this is a directional quantity and should be defined with respect to the interconnector flow.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last changed date of this record'))
    exportlimitconstraintid: Optional[str] = Field(default=None, sa_column=Column('exportlimitconstraintid', String(20), comment='ID of the constraint that sets the Interconnector Export Limit'))
    importlimitconstraintid: Optional[str] = Field(default=None, sa_column=Column('importlimitconstraintid', String(20), comment='ID of the constraint that sets the Interconnector Import Limit'))


class PdpasaRegionsolution(SQLModel, table=True):
    __tablename__ = 'pdpasa_regionsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runtype', 'interval_datetime', 'regionid', name='pdpasa_regionsolution_pk'),
        Index('pdpasa_regionsolution_lcx', 'lastchanged'),
        {'comment': 'The PDPASA region solution data'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Case identifier by the time the case was run'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='End date time of the interval'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region identifier'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR.'))
    demand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand10', Numeric(12, 2), comment='10% Probability of Exceedance demand forecast'))
    demand50: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand50', Numeric(12, 2), comment='50% Probability of Exceedance demand forecast'))
    demand90: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand90', Numeric(12, 2), comment='90% Probability of Exceedance demand forecast'))
    reservereq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservereq', Numeric(12, 2), comment='Region reserve requirement (MW)'))
    capacityreq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityreq', Numeric(12, 2), comment='Capacity required to meet the demand and reserve levels in the capacity adequacy assessment.'))
    energyreqdemand50: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energyreqdemand50', Numeric(12, 2), comment='Energy (GWh) required for this energy block based on the 50% probability of exceedance demand. Listed in the first interval of the energy block.'))
    unconstrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('unconstrainedcapacity', Numeric(12, 0), comment='Aggregate generator capability from Non Energy Constrained plant including restrictions due to network constraints from the capacity adequacy (LRC) assessment.'))
    constrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constrainedcapacity', Numeric(12, 0), comment='Aggregate generator capability from Energy Constrained plant including restrictions due to network constraints'))
    netinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('netinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the capacity adequacy (LRC) assessment.'))
    surpluscapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surpluscapacity', Numeric(12, 2), comment='Surplus capacity (MW) above the demand, scheduled load and net interchange in this region from the capacity adequacy (LRC) assessment.'))
    surplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surplusreserve', Numeric(12, 2), comment='Surplus reserve (MW) above the demand, scheduled load,  net interchange and reserve requirement in this region from the capacity adequacy (LRC) assessment.'))
    reservecondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservecondition', Numeric(1, 0), comment='Low Reserve Condition (LRC) flag for this region in this interval (1 - LRC, 0 - No LRC)'))
    maxsurplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsurplusreserve', Numeric(12, 2), comment='Maximum surplus reserve (MW) above the demand + reserve requirement able to be sourced to this region while meeting demand + reserve requirements in other regions.'))
    maxsparecapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsparecapacity', Numeric(12, 2), comment='Maximum spare capacity (MW) above the demand able to be sourced to this region while meeting demands in other regions.'))
    lorcondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lorcondition', Numeric(1, 0), comment='Lack of Reserve Condition (LOR) flag for this region and interval   (3 = LOR3, 2 = LOR2, 1 = LOR1, 0 = No LOR)'))
    aggregatecapacityavailable: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatecapacityavailable', Numeric(12, 2), comment='Sum of MAXAVAIL quantities offered by all Scheduled units and Availability of all semi-scheduled units limited by MAXAVAIL in a given Region for a given PERIODID'))
    aggregatescheduledload: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatescheduledload', Numeric(12, 2), comment='Sum of  MAXAVAIL quantities bid by of all Scheduled Loads in a given Region for a given PERIODID.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Date time the record was created or modified changed'))
    aggregatepasaavailability: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatepasaavailability', Numeric(12, 0), comment='Sum of PASAAVAILABILITY for all scheduled generating units and the Unconstrained Intermittent Generation Forecasts (UIGF) for all semi-scheduled generating units in a given Region for a given PERIODID.\r\nFor the RELIABILITY_LRC and OUTAGE_LRC runs, UIGF is the POE90 forecast. For the LOR run, UIGF is the POE50 forecast.'))
    energyreqdemand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energyreqdemand10', Numeric(12, 2), comment='Energy (GWh) required for this energy block based on the 10% probability of exceedance demand. Listed in the first interval of the energy block'))
    calculatedlor1level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor1level', Numeric(16, 6), comment='Region Reserve Level for LOR1 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    calculatedlor2level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor2level', Numeric(16, 6), comment='Region Reserve Level for LOR2 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    msrnetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('msrnetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the MSR assessment'))
    lornetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lornetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the LOR assessment'))
    totalintermittentgeneration: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalintermittentgeneration', Numeric(15, 5), comment='Allowance made for non-scheduled generation in the demand forecast (MW).'))
    demand_and_nonschedgen: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand_and_nonschedgen', Numeric(15, 5), comment='Sum of Cleared Scheduled generation, imported generation (at the region boundary) and allowances made for non-scheduled generation (MW).'))
    uigf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('uigf', Numeric(12, 2), comment='Regional aggregated Unconstrained Intermittent Generation Forecast of Semi-scheduled generation (MW).'))
    semischeduledcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('semischeduledcapacity', Numeric(12, 2), comment='Constrained generation forecast for semi-scheduled units for the region. For RELIABILITY_LRC run semi-scheduled generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run semi-scheduled generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    lor_semischeduledcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lor_semischeduledcapacity', Numeric(12, 2), comment='Constrained generation forecast for semi-scheduled units for the region for the LOR run. Semi-scheduled generation is constrained by both System Normal and Outage constraints, and incorporate MAXAVAIL limits.'))
    lcr: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lcr', Numeric(16, 6), comment='Largest Credible Risk. MW value for highest credible contingency'))
