    ss_solar_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_solar_capacity', Numeric(12, 2), comment='Constrained generation forecast for solar for the region. For RELIABILITY_LRC run solar generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run solar generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_wind_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_wind_capacity', Numeric(12, 2), comment='Constrained generation forecast for wind for the region. For RELIABILITY_LRC run wind generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run wind generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_solar_cleared: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_solar_cleared', Numeric(12, 2), comment='Constrained generation forecast for solar for the region. For RELIABILITY_LRC run solar generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run solar generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_wind_cleared: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_wind_cleared', Numeric(12, 2), comment='Constrained generation forecast for wind for the region. For RELIABILITY_LRC run wind generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run wind generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    wdr_available: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_available', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) availability in MW.'))
    wdr_pasaavailable: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_pasaavailable', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) PASA availability in MW.'))
    wdr_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_capacity', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) capacity in MW.'))


