    duid: Optional[str] = Field(default=None, sa_column=Column('duid', String(20), comment='DUID to which the Constraint is confidential. Null denotes non-confidential'))
    genconid_effectivedate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('genconid_effectivedate', TIMESTAMP(precision=0), comment='Effective date of the Generic Constraint (ConstraintID). This field is used to track the version of this generic constraint applied in this dispatch interval'))
