    marginal6secvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('marginal6secvalue', Numeric(15, 5), comment='Marginal $ value for 6 seconds from LP Solver'))
    marginalvalue: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('marginalvalue', Numeric(15, 5), comment='Marginal $ value for energy from LP Solver'))
    violation5mindegree: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('violation5mindegree', Numeric(15, 5), comment='Violation MW 5 min'))
    violation60secdegree: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('violation60secdegree', Numeric(15, 5), comment='Violation MW 60 seconds'))
