class Predispatchoffertrk(SQLModel, table=True):
    __table_args__ = (
        PrimaryKeyConstraint('predispatchseqno', 'duid', 'bidtype', 'periodid', name='predispatchoffertrk_pk'),
        Index('predispatchoffertrk_lchd_idx', 'lastchanged'),
        {'comment': 'PREDISPATCHOFFERTRK is for the ancillary service bid tracking of '
                'predispatch processing. PREDISPATCHOFFERTRK identifies which bids '
                'from BIDDAYOFFER and BIDOFFERPERIOD were applied for a given unit '
                'and ancillary service for each predispatch run.'}
    )

    predispatchseqno: str = Field(sa_column=Column('predispatchseqno', String(20), primary_key=True, comment='Unique identifier of predispatch run in the form YYYYMMDDPP with 01 at 04:30'))
    duid: str = Field(sa_column=Column('duid', String(10), primary_key=True, comment='Dispatchable Unit identifier'))
    bidtype: str = Field(sa_column=Column('bidtype', String(20), primary_key=True, comment='Bid type Identifier - the ancillary service to which the bid applies'))
    periodid: str = Field(sa_column=Column('periodid', String(20), primary_key=True, comment='PERIODID is just a period count, starting from 1 for each predispatch run. Use DATETIME to determine half hour period.'))
    bidsettlementdate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('bidsettlementdate', TIMESTAMP(precision=0), comment='Settlement date of bid applied'))
    bidofferdate: Optional[datetime.datetime] = Field(default=None, sa_column=Column('bidofferdate', TIMESTAMP(precision=3), comment='Time this bid was processed and loaded'))
    datetime: Optional[datetime.datetime] = Field(default=None, sa_column=Column('datetime', TIMESTAMP(precision=0), comment='Period date and time'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))


