    stationid: str = Field(sa_column=Column('stationid', String(10), primary_key=True, comment='Station Identifier'))
    duid: str = Field(sa_column=Column('duid', String(10), primary_key=True, comment='Dispatchable Unit identifier'))
    gensetid: str = Field(sa_column=Column('gensetid', String(10), primary_key=True, comment='Physical unit identifier'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region Identifier'))
    participantid: Optional[str] = Field(default=None, sa_column=Column('participantid', String(10), comment='Unique participant identifier'))
    genergy: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('genergy', Numeric(16, 6), comment='Generated energy'))
    aenergy: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aenergy', Numeric(16, 6), comment='Purchased Energy'))
    gpower: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('gpower', Numeric(16, 6), comment='Not used'))
    apower: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('apower', Numeric(16, 6), comment='Not used'))
    rrp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rrp', Numeric(20, 5), comment='Regional Reference Price'))
    eep: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('eep', Numeric(16, 6), comment='Excess Energy Price'))
    tlf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('tlf', Numeric(7, 5), comment='Transmission Loss Factor'))
    cprrp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('cprrp', Numeric(16, 6), comment='Connection Point Price = RRP * TLF'))
    cpeep: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('cpeep', Numeric(16, 6), comment='Connection Point Excess Energy Price = EEP * TLF'))
    netenergy: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('netenergy', Numeric(16, 6), comment='Generated energy'))
    energycost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energycost', Numeric(16, 6), comment='Cost of net energy $'))
    excessenergycost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('excessenergycost', Numeric(16, 6), comment='Cost of excess energy $'))
    apc: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('apc', Numeric(16, 6), comment='Administered Price Compensation'))
    resc: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('resc', Numeric(16, 6), comment='Not used'))
    resp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('resp', Numeric(16, 6), comment='Not used'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))
    expenergy: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('expenergy', Numeric(15, 6), comment='Export Energy (Generator Purchases) (MWh)'))
    expenergycost: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('expenergycost', Numeric(15, 6), comment='Export Energy Cost ($)'))
    meterrunno: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('meterrunno', Numeric(6, 0), comment='Identifier of the meter run used in this settlement calculation'))
    mda: Optional[str] = Field(default=None, sa_column=Column('mda', String(10), comment='Metering Data Agent'))
    secondary_tlf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('secondary_tlf', Numeric(7, 5), comment='Secondary Transmission Loss Factor'))


