    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    constraintid: str = Field(sa_column=Column('constraintid', String(20), primary_key=True, comment='Constraint identifier (synonymous with GenConID)'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR.'))
    studyregionid: str = Field(sa_column=Column('studyregionid', String(20), primary_key=True, server_default=text("'MARKET'::character varying"), comment='Primary Region for LP Solve (or MARKET if none).'))
    capacityrhs: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityrhs', Numeric(12, 2), comment='The RHS value in the capacity evaluation.'))
