class StpasaRegionsolution(SQLModel, table=True):
    __tablename__ = 'stpasa_regionsolution'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'runtype', 'interval_datetime', 'regionid', name='regionsolution_pk'),
        Index('stpasa_regionsolution_lcx', 'lastchanged'),
        {'comment': 'STPASA_REGIONSOLUTION shows the results of the regional capacity, '
                'maximum surplus reserve and maximum spare capacity evaluations '
                'for each period of the study.'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Unique Timestamp Identifier for this study'))
    interval_datetime: datetime.datetime = Field(sa_column=Column('interval_datetime', TIMESTAMP(precision=0), primary_key=True, comment='The unique identifier for the interval within this study'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region Identifier'))
    runtype: str = Field(sa_column=Column('runtype', String(20), primary_key=True, server_default=text("'OUTAGE_LRC'::character varying"), comment='Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR.'))
    demand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand10', Numeric(12, 2), comment='Input value for 10% probability demand'))
    demand50: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand50', Numeric(12, 2), comment='Input value for 50% probability demand'))
    demand90: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand90', Numeric(12, 2), comment='Input value for 90% probability demand'))
    reservereq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservereq', Numeric(12, 2), comment='Input reserve requirement'))
    capacityreq: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('capacityreq', Numeric(12, 2), comment='Demand + Reserve Requirement'))
    energyreqdemand50: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energyreqdemand50', Numeric(12, 2), comment='Sum of: (Region Period Demand - given Demand50)/Period (sum by trading day, entered in first period of trading day, GWh)'))
    unconstrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('unconstrainedcapacity', Numeric(12, 0), comment='In a Region, capacity from generation/Load with no Daily Energy Constraint, subject to network security constraints'))
    constrainedcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('constrainedcapacity', Numeric(12, 0), comment='In a Region, capacity from generation/Load with non-zero Daily Energy Constraint, subject to network security constraints'))
    netinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('netinterchangeunderscarcity', Numeric(12, 2), comment='Net export in MW out of this region in the capacity adequacy evaluation. Export if > 0, Import if < 0.'))
    surpluscapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surpluscapacity', Numeric(12, 2), comment='Regional surplus capacity MW, +/- values indicate surplus/deficit capacity respectively'))
    surplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('surplusreserve', Numeric(12, 2), comment='Regional reserve surplus. +/- values indicate surplus/deficit reserve respectively'))
    reservecondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('reservecondition', Numeric(1, 0), comment='The regional reserve condition: 0  Adequate, 1  LRC'))
    maxsurplusreserve: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsurplusreserve', Numeric(12, 2), comment='The Maximum Surplus Reserve evaluated for this region in this period.  Calculated for each region in turn.'))
    maxsparecapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('maxsparecapacity', Numeric(12, 2), comment='The Maximum Spare Capacity evaluated for this region in this period. Calculated for each region in turn.'))
    lorcondition: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lorcondition', Numeric(1, 0), comment='The LOR Condition determined from the Maximum Spare Capacity value: 0 - no condition, 1 - LOR1 condition, 2 - LOR2 condition, 3 - LOR3 condition'))
    aggregatecapacityavailable: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatecapacityavailable', Numeric(12, 2), comment='Sum of MAXAVAIL quantities offered by all Scheduled units and Availability of all semi-scheduled units limited by MAXAVAIL in a given Region for a given PERIODID'))
    aggregatescheduledload: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatescheduledload', Numeric(12, 2), comment='Sum of  MAXAVAIL quantities bid by of all Scheduled Loads in a given Region for a given PERIODID.'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last changed date of this record'))
    aggregatepasaavailability: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('aggregatepasaavailability', Numeric(12, 0), comment='Sum of PASAAVAILABILITY for all scheduled generating units and the Unconstrained Intermittent Generation Forecasts (UIGF) for all semi-scheduled generating units in a given Region for a given PERIODID.\r\nFor the RELIABILITY_LRC and OUTAGE_LRC runs, UIGF is the POE90 forecast. For the LOR run, UIGF is the POE50 forecast.'))
    energyreqdemand10: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('energyreqdemand10', Numeric(12, 2), comment='Energy (GWh) required for this energy block based on the 10% probability of exceedance demand. Listed in the first interval of the energy block'))
    calculatedlor1level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor1level', Numeric(16, 6), comment='Region Reserve Level for LOR1 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    calculatedlor2level: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('calculatedlor2level', Numeric(16, 6), comment='Region Reserve Level for LOR2 used. Can be static value or calculated value if an interconnector is a credible contingency'))
    msrnetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('msrnetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the MSR assessment'))
    lornetinterchangeunderscarcity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lornetinterchangeunderscarcity', Numeric(12, 2), comment='Net interconnector flow from the region for this interval from the LOR assessment'))
    totalintermittentgeneration: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('totalintermittentgeneration', Numeric(15, 5), comment='Allowance made for non-scheduled generation in the demand forecast (MW).'))
    demand_and_nonschedgen: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('demand_and_nonschedgen', Numeric(15, 5), comment='Sum of Cleared Scheduled generation, imported generation (at the region boundary) and allowances made for non-scheduled generation (MW).'))
    uigf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('uigf', Numeric(12, 2), comment='Regional aggregated Unconstrained Intermittent Generation Forecast of Semi-scheduled generation (MW).'))
    semischeduledcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('semischeduledcapacity', Numeric(12, 2), comment='Constrained generation forecast for semi-scheduled units for the region. For RELIABILITY_LRC run semi-scheduled generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run semi-scheduled generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    lor_semischeduledcapacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lor_semischeduledcapacity', Numeric(12, 2), comment='Constrained generation forecast for semi-scheduled units for the region for the LOR run type. Semi-scheduled generation is constrained by both System Normal and Outage constraints, and incorporate MAXAVAIL limits.'))
    lcr: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lcr', Numeric(16, 6), comment='Largest Credible Risk. MW value for highest credible contingency'))
    lcr2: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('lcr2', Numeric(16, 6), comment='Two Largest Creditable Risks. MW value for highest two credible contingencies.'))
    fum: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('fum', Numeric(16, 6), comment='Forecasting Uncertainty Measure. MW value of reserve calculated as defined in the Reserve Level Declaration Guidelines'))
    ss_solar_uigf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_solar_uigf', Numeric(12, 2), comment='Unconstrained Intermittent Generation Forecast for solar for the region. For RELIABILITY_LRC and OUTAGE_LRC run this is the POE90 forecast (determined by LRCUIGFOption in CaseSolution). For LOR run this is the POE50 forecast'))
    ss_wind_uigf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_wind_uigf', Numeric(12, 2), comment='Unconstrained Intermittent Generation Forecast for wind for the region. For RELIABILITY_LRC and OUTAGE_LRC run this is the POE90 forecast (determined by LRCUIGFOption in CaseSolution). For LOR run this is the POE50 forecast'))
    ss_solar_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_solar_capacity', Numeric(12, 2), comment='Constrained generation forecast for solar for the region. For RELIABILITY_LRC run solar generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run solar generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_wind_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_wind_capacity', Numeric(12, 2), comment='Constrained generation forecast for wind for the region. For RELIABILITY_LRC run wind generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run wind generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_solar_cleared: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_solar_cleared', Numeric(12, 2), comment='Constrained generation forecast for solar for the region. For RELIABILITY_LRC run solar generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run solar generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    ss_wind_cleared: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('ss_wind_cleared', Numeric(12, 2), comment='Constrained generation forecast for wind for the region. For RELIABILITY_LRC run wind generation is constrained only by System Normal constraints. For OUTAGE_LRC run and LOR run wind generation is constrained by both System Normal and Outage constraints. All three run types (RELIABILITY_LRC, OUTAGE_LRC, LOR) incorporate MAXAVAIL limits.'))
    wdr_available: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_available', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) availability in MW.'))
    wdr_pasaavailable: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_pasaavailable', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) PASA availability in MW.'))
    wdr_capacity: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('wdr_capacity', Numeric(12, 2), comment='Regional aggregated Wholesale Demand Response (WDR) capacity in MW.'))


