    periodid: decimal.Decimal = Field(sa_column=Column('periodid', Numeric(3, 0), primary_key=True, comment='Period number where 1 represents the trading interval ending at 00:05 AEST'))
    meteredmwflow: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('meteredmwflow', Numeric(15, 5), comment='Average of the metered MW flow from the start of each dispatch interval.'))
    mwflow: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('mwflow', Numeric(15, 5), comment='Calculated MW Flow from SPD'))
    mwlosses: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('mwlosses', Numeric(15, 5), comment='MW losses at calculated MW flow'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Last date and time record changed'))


