class Tradingprice(SQLModel, table=True):
    __table_args__ = (
        PrimaryKeyConstraint('settlementdate', 'runno', 'regionid', 'periodid', name='pk_tradingprice'),
        Index('tradingprice_lcx', 'lastchanged'),
        {'comment': 'TRADINGPRICE sets out 5 minutes spot market price, including '
                'fields to handle the Ancillary Services functionality. If prices '
                'are adjusted, the final price is recorded in the regional '
                'reference price (RRP) field with price before adjustment recorded '
                'in the regional original price (ROP) field.\r\n'
                'Prior to 5 Minute Settlements, this was half-hourly spot market '
                'values, which was calculated as the average of the six 5 minute '
                'dispatch intervals within the 30 minute period.'}
    )

    settlementdate: datetime.datetime = Field(sa_column=Column('settlementdate', TIMESTAMP(precision=0), primary_key=True, comment='Date that this data applies to'))
    runno: decimal.Decimal = Field(sa_column=Column('runno', Numeric(3, 0), primary_key=True, comment='Run No'))
    regionid: str = Field(sa_column=Column('regionid', String(10), primary_key=True, comment='Region Identifier'))
    periodid: decimal.Decimal = Field(sa_column=Column('periodid', Numeric(3, 0), primary_key=True, comment='Period number where 1 represents the trading interval ending at 00:05 AEST'))
    rrp: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('rrp', Numeric(15, 5), comment='Regional reference price for this dispatch period'))
    eep: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('eep', Numeric(15, 5), comment='Excess energy price where negative average'))
