class Transmissionlossfactor(SQLModel, table=True):
    __table_args__ = (
        PrimaryKeyConstraint('connectionpointid', 'effectivedate', 'versionno', name='transmissionlossfactor_pk'),
        Index('transmissionlossfactor_lcx', 'lastchanged'),
        {'comment': 'TRANSMISSIONLOSSFACTOR shows the Transmission Loss factors '
                'applied at each connection point.'}
    )

    transmissionlossfactor: decimal.Decimal = Field(sa_column=Column('transmissionlossfactor', Numeric(15, 5), nullable=False, comment='Used in Bidding, Dispatch and Settlements. For Bidding and Dispatch, where the DUID is a BDU with DISPATCHTYPE of BIDIRECTIONAL, the TLF for the load component of the BDU. For Settlements, where dual TLFs apply, the primary TLF is applied to all energy (load and generation) when the Net Energy Flow of the ConnectionPointID in the interval is negative (net load).'))
    effectivedate: datetime.datetime = Field(sa_column=Column('effectivedate', TIMESTAMP(precision=0), primary_key=True, comment='Effective date of record'))
    versionno: decimal.Decimal = Field(sa_column=Column('versionno', Numeric(22, 0), primary_key=True, comment='Version no of record for given effective date'))
    connectionpointid: str = Field(sa_column=Column('connectionpointid', String(10), primary_key=True, comment='Connection Point ID'))
    regionid: Optional[str] = Field(default=None, sa_column=Column('regionid', String(10), comment='Region Identifier'))
    lastchanged: Optional[datetime.datetime] = Field(default=None, sa_column=Column('lastchanged', TIMESTAMP(precision=0), comment='Record creation timestamp'))
    secondary_tlf: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('secondary_tlf', Numeric(18, 8), comment='Used in Bidding, Dispatch and Settlements, only populated where Dual TLFs apply. For Bidding and Dispatch, the TLF for the generation component of a BDU, when null the TRANSMISSIONLOSSFACTOR is used for both the load and generation components. For Settlements, the secondary TLF is applied to all energy (load and generation) when the Net Energy Flow of the ConnectionPointID in the interval is positive (net generation).'))


