class VoltageInstruction(SQLModel, table=True):
    __tablename__ = 'voltage_instruction'
    __table_args__ = (
        PrimaryKeyConstraint('run_datetime', 'version_datetime', 'ems_id', name='voltage_instruction_pk'),
        {'comment': 'Child record for Voltage Instructions (MVAr Dispatch)'}
    )

    run_datetime: datetime.datetime = Field(sa_column=Column('run_datetime', TIMESTAMP(precision=0), primary_key=True))
    ems_id: str = Field(sa_column=Column('ems_id', String(60), primary_key=True))
    version_datetime: datetime.datetime = Field(sa_column=Column('version_datetime', TIMESTAMP(precision=0), primary_key=True, comment='Datetime the file was published by VDS - Versions differ from Run_DateTime only for Supplemental runs'))
    participantid: Optional[str] = Field(default=None, sa_column=Column('participantid', String(20), comment='The NEM id of the participant who owns the equipment'))
    station_id: Optional[str] = Field(default=None, sa_column=Column('station_id', String(60), comment='The id of the station where the control equipment resides'))
    device_id: Optional[str] = Field(default=None, sa_column=Column('device_id', String(60), comment='The company/participant preferred name of an equipment'))
    device_type: Optional[str] = Field(default=None, sa_column=Column('device_type', String(20), comment='One of REACTOR, CAPACITOR, GEN, SVC, TRANS or GRPGEN but may be extended to other types'))
    control_type: Optional[str] = Field(default=None, sa_column=Column('control_type', String(20), comment='One of VOLTAGE, TAP, MVAR, SWITCH or COMMIT but may be extended to other types'))
    target: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('target', Numeric(20, 5), comment='Instruction for the device, for this interval null denotes no instruction'))
    conforming: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('conforming', Numeric(1, 0), comment='[0,1] Denotes if the Device is currently conforming'))
    instruction_summary: Optional[str] = Field(default=None, sa_column=Column('instruction_summary', String(400), comment='Verbose summary of instruction'))
    instruction_sequence: Optional[decimal.Decimal] = Field(default=None, sa_column=Column('instruction_sequence', Numeric(4, 0), comment='Order for execution of Instruction'))
    additional_notes: Optional[str] = Field(default=None, sa_column=Column('additional_notes', String(60), comment='Additional information pertaining to a particular instruction, e.g. Previously issued instruction revoked'))


